"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.attendance import days_missed

def check_marks(student: Student, marks: list) -> None:
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )

def join_days(days: list) -> str:
    return ", ".join(day.isoformat() for day in days)

# ---
def build_notice(student: Student, marks: list) -> str:
    """Short notice naming the student and absent days."""
    check_marks(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to write about")
    name = f"{student.first_name} {student.last_name}"
    dates = join_days(days)
    return f"{name} missed {len(days)} day(s): {dates}."
